import{_ as l,C as s,o as d,c as e,j as i,a as t,E as r,a2 as n}from"./chunks/framework.C21TwvGF.js";const V=JSON.parse(`{"title":"11-dars (Mentor). 11-dars: Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (1-qism)","description":"","frontmatter":{"title":"11-dars (Mentor). 11-dars: Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (1-qism)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"week":{"n":4,"link":"/mentor/9-sinf-iot/hafta-04/"},"g":11,"title":"11-dars: Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (1-qism)","lead":"Uydagi chiroq kalitini bosganingizda nima sodir bo'ladi? Siz shunchaki elektr zanjirini yopasiz yoki ochasiz. Bugun dasturisiz, faqat breadboard, DIP switch va LED bilan shunday zanjirni o'zimiz yig'amiz.","slide":"/slaydlar/9-sinf-iot/hafta-04/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-04/dars-2-test.html","student_link":"/9-sinf-iot/hafta-04/dars-2","tabs":[{"g":10,"link":"/mentor/9-sinf-iot/hafta-04/dars-1","current":false},{"g":11,"link":"/mentor/9-sinf-iot/hafta-04/dars-2","current":true},{"g":12,"link":"/mentor/9-sinf-iot/hafta-04/dars-3","current":false}],"prev":{"g":10,"title":"10-dars: Arduino UNO va tugma orqali LED holatini boshqarish dasturi","link":"/mentor/9-sinf-iot/hafta-04/dars-1"},"next":{"g":12,"title":"12-dars: Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish (2-qism)","link":"/mentor/9-sinf-iot/hafta-04/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-04/dars-2.md","filePath":"mentor/9-sinf-iot/hafta-04/dars-2.md"}`),h={name:"mentor/9-sinf-iot/hafta-04/dars-2.md"},k={class:"blk"},u={id:"darsning-maqsadi",tabindex:"-1"},m={class:"blk"},b={id:"kutilayotgan-natijalar-o-quvchi-bilishi-kerak",tabindex:"-1"},g={class:"blk"},q={id:"kerakli-jihozlar-va-vositalar",tabindex:"-1"},y={class:"blk"},c={id:"dars-rejasi-80-daqiqa",tabindex:"-1"},p={class:"blk"},z={id:"nazariy-ma-lumotlar",tabindex:"-1"},D={class:"blk"},v={id:"amaliy-mashg-ulot-va-topshiriqlar",tabindex:"-1"},f={class:"blk"},P={id:"tezkor-nazorat-savollari",tabindex:"-1"},T={class:"blk"},_={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function I(E,a,j,x,O,L){const o=s("Icon");return d(),e("div",null,[a[26]||(a[26]=i("p",null,[i("strong",null,"Fan:"),t(" Internet of Things (IoT — Buyumlar Interneti)"),i("br"),i("strong",null,"Sinf:"),t(" 9-sinf"),i("br"),i("strong",null,"Hafta:"),t(" 4-hafta, 2-dars (umumiy 11-dars)"),i("br"),i("strong",null,"Dars davomiyligi:"),t(" 80 daqiqa")],-1)),a[27]||(a[27]=i("hr",null,null,-1)),i("div",k,[i("h2",u,[r(o,{name:"file-text"}),a[0]||(a[0]=t(" Darsning maqsadi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#darsning-maqsadi","aria-label":'Permalink to "<Icon name="file-text" /> Darsning maqsadi"'},"​",-1))]),a[2]||(a[2]=i("p",null,[t("O'quvchilarga mikrokontrollersiz eng oddiy "),i("strong",null,"elektr zanjiri (sikl)"),t(" — manba, kalit, rezistor va LED — tuzilishini, uning "),i("strong",null,"ochiq va yopiq"),t(" holatlarini, breadboard ichki ulanishlarini, kalitlar turlari (SPST, SPDT, DPST, DPDT) va "),i("strong",null,"DIP switch"),t(" tuzilishini o'rgatish; Om qonuni asosida LED uchun rezistor qiymatini hisoblash va Tinkercad'da DIP switch orqali LEDni yoqib-o'chiradigan sxemani yig'ish ko'nikmasini shakllantirish.")],-1)),a[3]||(a[3]=i("hr",null,null,-1))]),i("div",m,[i("h2",b,[r(o,{name:"file-text"}),a[4]||(a[4]=t(" Kutilayotgan natijalar (O'quvchi bilishi kerak) ",-1)),a[5]||(a[5]=i("a",{class:"header-anchor",href:"#kutilayotgan-natijalar-o-quvchi-bilishi-kerak","aria-label":`Permalink to "<Icon name="file-text" /> Kutilayotgan natijalar (O'quvchi bilishi kerak)"`},"​",-1))]),a[6]||(a[6]=n("<ul><li>Elektr zanjirining 4 ta asosiy qismini (manba, o&#39;tkazgich, iste&#39;molchi, kalit) ayta olish;</li><li>Ochiq va yopiq zanjir farqini tushuntira olish: tok faqat <strong>yopiq</strong> zanjirda oqadi;</li><li>Breadboardda qaysi teshiklar o&#39;zaro ulanganini (quvvat relslari, 5 teshikli ustunlar, markaziy ariqcha) bilish;</li><li>Pole (qutb) va throw (yo&#39;nalish) tushunchalari orqali SPST, SPDT, DPST, DPDT kalitlarini farqlay olish;</li><li>DIP switch nima ekanini va har bir juft kontakt mustaqil kalit ekanini bilish;</li><li>Om qonuni bo&#39;yicha rezistor qiymatini hisoblay olish: <code>R = (U − U_LED) / I</code>;</li><li>Tinkercad&#39;da manba → DIP switch → rezistor → LED → GND zanjirini yig&#39;ib, sinab ko&#39;ra olish.</li></ul><hr>",2))]),i("div",g,[i("h2",q,[r(o,{name:"file-text"}),a[7]||(a[7]=t(" Kerakli jihozlar va vositalar ",-1)),a[8]||(a[8]=i("a",{class:"header-anchor",href:"#kerakli-jihozlar-va-vositalar","aria-label":'Permalink to "<Icon name="file-text" /> Kerakli jihozlar va vositalar"'},"​",-1))]),a[9]||(a[9]=i("ul",null,[i("li",null,"Kompyuter yoki noutbuk (internetga ulangan), Tinkercad.com (Circuits);"),i("li",null,"Real to'plam (bo'lsa): breadboard, DIP switch (2 pozitsiyali), LEDlar, 220–330 Om rezistorlar, ulash simlari, 5V manba yoki 9V batareya (uslubiy ko'rsatma);"),i("li",null,"Proyektor yoki monitor (namoyish uchun).")],-1)),a[10]||(a[10]=i("hr",null,null,-1))]),i("div",y,[i("h2",c,[r(o,{name:"file-text"}),a[11]||(a[11]=t(" Dars rejasi (80 daqiqa) ",-1)),a[12]||(a[12]=i("a",{class:"header-anchor",href:"#dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi (80 daqiqa)"'},"​",-1))]),a[13]||(a[13]=n('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 min</strong></td><td>Takrorlash</td><td>LED anod/katod, rezistor vazifasi, 10-darsdagi «holat» tushunchasi</td></tr><tr><td><strong>10–25 min</strong></td><td>Yangi mavzu: elektr zanjiri</td><td>Manba, o&#39;tkazgich, iste&#39;molchi, kalit; ochiq va yopiq zanjir</td></tr><tr><td><strong>25–35 min</strong></td><td>Breadboard tuzilishi</td><td>Quvvat relslari, terminal ustunlari, markaziy ariqcha</td></tr><tr><td><strong>35–45 min</strong></td><td>Kalitlar va DIP switch</td><td>SPST, SPDT, DPST, DPDT; DIP korpus, ON tomoni</td></tr><tr><td><strong>45–55 min</strong></td><td>Om qonuni va rezistor hisobi</td><td>5V va 9V manba uchun misollar</td></tr><tr><td><strong>55–75 min</strong></td><td>Amaliy laboratoriya</td><td>Tinkercad&#39;da DIP switch + LED zanjiri, ochiq/yopiq holat sinovi</td></tr><tr><td><strong>75–80 min</strong></td><td>Xulosa va uyga vazifa</td><td>Mavzuni umumlashtirish</td></tr></tbody></table><blockquote><p>Manba: o&#39;quv dasturi — «Breadboardda DIP switch (DPST) va LED yordamida oddiy elektron sikl yaratish» (komponentlarni to&#39;g&#39;ri joylashtirish, DIP switch orqali signal boshqarish, LED bilan holatni ko&#39;rsatish, ochiq va yopiq holat, xatolarni aniqlash); uslubiy ko&#39;rsatma — kerakli jihozlar (breadboard, DIP switch DPST, LED, 220–330 Om rezistor, simlar, 9V yoki 5V manba, Tinkercad), ulash tartibi va «dastur yozilmaydi, chunki mikrokontrollerdan foydalanmadik».</p></blockquote><hr>',3))]),i("div",p,[i("h2",z,[r(o,{name:"file-text"}),a[14]||(a[14]=t(" Nazariy ma'lumotlar ",-1)),a[15]||(a[15]=i("a",{class:"header-anchor",href:"#nazariy-ma-lumotlar","aria-label":`Permalink to "<Icon name="file-text" /> Nazariy ma'lumotlar"`},"​",-1))]),a[16]||(a[16]=n(`<h3 id="_1-elektr-zanjiri-sikl-nima" tabindex="-1">1. Elektr zanjiri (sikl) nima? <a class="header-anchor" href="#_1-elektr-zanjiri-sikl-nima" aria-label="Permalink to &quot;1. Elektr zanjiri (sikl) nima?&quot;">​</a></h3><p><strong>Elektr zanjiri</strong> — tok manbadan chiqib, iste&#39;molchidan o&#39;tib, yana manbaga qaytadigan <strong>berk yo&#39;l</strong>. Uslubiy ko&#39;rsatmada bu «elektron sikl» deb ataladi: tok sikl bo&#39;ylab aylanadi.</p><table tabindex="0"><thead><tr><th>Qism</th><th>Vazifasi</th><th>Bizning sxemada</th></tr></thead><tbody><tr><td>Manba</td><td>Kuchlanish beradi (+ va −)</td><td>5V manba yoki 9V batareya</td></tr><tr><td>O&#39;tkazgich</td><td>Tokni olib boradi</td><td>ulash simlari, breadboard ichki plastinkalari</td></tr><tr><td>Iste&#39;molchi</td><td>Energiyani ishga aylantiradi</td><td>LED (yorug&#39;lik)</td></tr><tr><td>Kalit</td><td>Zanjirni ochadi yoki yopadi</td><td>DIP switch</td></tr><tr><td>Himoya</td><td>Tokni cheklaydi</td><td>rezistor 220–330 Om</td></tr></tbody></table><ul><li><strong>Yopiq zanjir:</strong> kalit yoqilgan (ON), yo&#39;l uzluksiz → tok oqadi → LED yonadi.</li><li><strong>Ochiq zanjir:</strong> kalit o&#39;chirilgan (OFF) yoki sim uzilgan → tok oqmaydi → LED o&#39;chiq.</li></ul><p>Bu 10-darsdagi «holat» ning eng oddiy shakli: kalitning holati to&#39;g&#39;ridan-to&#39;g&#39;ri LED holatini belgilaydi, <strong>dastur yozilmaydi</strong>.</p><h3 id="_2-breadboard-tuzilishi" tabindex="-1">2. Breadboard tuzilishi <a class="header-anchor" href="#_2-breadboard-tuzilishi" aria-label="Permalink to &quot;2. Breadboard tuzilishi&quot;">​</a></h3><p><strong>Breadboard</strong> — komponentlarni payvandlashsiz ulash uchun teshikli plata. Ichida metall plastinkalar teshiklarni guruhlab ulaydi:</p><table tabindex="0"><thead><tr><th>Qism</th><th>Qanday ulangan</th><th>Nima uchun</th></tr></thead><tbody><tr><td>Quvvat relslari (<code>+</code> qizil, <code>−</code> ko&#39;k chiziq)</td><td>Butun uzunlik bo&#39;ylab <strong>gorizontal</strong></td><td>Manbaning <code>+</code> va GND ini tarqatish</td></tr><tr><td>Terminal ustunlari (a–e, f–j)</td><td>Har bir raqamli qatorda <strong>5 ta teshik</strong> o&#39;zaro ulangan</td><td>Komponent oyoqlarini bir-biriga ulash</td></tr><tr><td>Markaziy ariqcha</td><td>Ikki yarmini <strong>ajratadi</strong></td><td>DIP korpusli detallarni ustiga qo&#39;yish uchun</td></tr></tbody></table><p>Qoida: bitta komponentning ikki oyog&#39;i <strong>bir xil 5 teshikli qatorga</strong> tushsa, u qisqa tutashadi va ishlamaydi.</p><h3 id="_3-kalitlar-turlari-pole-va-throw" tabindex="-1">3. Kalitlar turlari: pole va throw <a class="header-anchor" href="#_3-kalitlar-turlari-pole-va-throw" aria-label="Permalink to &quot;3. Kalitlar turlari: pole va throw&quot;">​</a></h3><ul><li><strong>Pole (qutb)</strong> — kalit nechta <strong>mustaqil zanjirni</strong> boshqaradi.</li><li><strong>Throw (yo&#39;nalish)</strong> — har bir qutb nechta <strong>holatga</strong> ulana oladi.</li></ul><table tabindex="0"><thead><tr><th>Tur</th><th>To&#39;liq nomi</th><th>Ma&#39;nosi</th><th>Misol</th></tr></thead><tbody><tr><td>SPST</td><td>Single Pole, Single Throw</td><td>1 zanjir, yoq/o&#39;chir</td><td>oddiy chiroq kaliti</td></tr><tr><td>SPDT</td><td>Single Pole, Double Throw</td><td>1 zanjir, 2 yo&#39;nalishdan biri</td><td>ikki joydan boshqariladigan chiroq</td></tr><tr><td>DPST</td><td>Double Pole, Single Throw</td><td>2 zanjir, yoq/o&#39;chir</td><td>ikki simni birga uzuvchi kalit</td></tr><tr><td>DPDT</td><td>Double Pole, Double Throw</td><td>2 zanjir, 2 yo&#39;nalish</td><td>motor yo&#39;nalishini almashtirish</td></tr></tbody></table><h3 id="_4-dip-switch" tabindex="-1">4. DIP switch <a class="header-anchor" href="#_4-dip-switch" aria-label="Permalink to &quot;4. DIP switch&quot;">​</a></h3><p><strong>DIP switch</strong> (Dual In-line Package) — mikrosxema korpusiga o&#39;xshash, ikki qator oyoqli kichik blok; ichida bir nechta <strong>kichik kalit</strong> (2, 4, 8 pozitsiya) bor. Har bir richag <strong>bir juft kontaktni</strong> ulaydi yoki uzadi.</p><ul><li>Uslubiy ko&#39;rsatma va Tinkercad&#39;dagi <strong>DIP Switch DPST</strong> — 2 pozitsiyali blok: <strong>ikki juft kontakt</strong>, har biri o&#39;z richagi bilan <strong>mustaqil</strong> boshqariladi.</li><li>Korpusda <strong>ON</strong> yozuvi bor: richag shu tomonga surilsa — kontakt yopiq.</li><li>Breadboardga <strong>markaziy ariqcha ustiga</strong> qo&#39;yiladi: shunda har bir oyoq alohida qatorga tushadi va juft kontaktlar bir-biri bilan qisqa tutashmaydi.</li><li>Qo&#39;llanishi: qurilma manzilini yoki rejimini <strong>bir marta sozlash</strong> (router, pult, sanoat qurilmalari).</li></ul><h3 id="_5-om-qonuni-va-rezistor-hisobi" tabindex="-1">5. Om qonuni va rezistor hisobi <a class="header-anchor" href="#_5-om-qonuni-va-rezistor-hisobi" aria-label="Permalink to &quot;5. Om qonuni va rezistor hisobi&quot;">​</a></h3><p><code>U = I × R</code> (kuchlanish = tok × qarshilik). LED uchun:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>R = (U_manba − U_LED) / I</span></span></code></pre></div><ul><li><code>U_LED</code> — LED dagi kuchlanish tushishi: qizil ≈ 2 V, yashil/ko&#39;k ≈ 3 V;</li><li><code>I</code> — xavfsiz tok: 10–15 mA (0,010–0,015 A), maksimal ≈ 20 mA.</li></ul><table tabindex="0"><thead><tr><th>Manba</th><th>LED</th><th>Hisob</th><th>Tanlov</th></tr></thead><tbody><tr><td>5 V</td><td>qizil (2 V), 10 mA</td><td>(5 − 2) / 0,010 = 300 Om</td><td><strong>330 Om</strong></td></tr><tr><td>5 V</td><td>qizil (2 V), 14 mA</td><td>(5 − 2) / 0,014 ≈ 214 Om</td><td><strong>220 Om</strong></td></tr><tr><td>9 V</td><td>qizil (2 V), 15 mA</td><td>(9 − 2) / 0,015 ≈ 467 Om</td><td><strong>470 Om</strong></td></tr></tbody></table><p>Shuning uchun uslubiy ko&#39;rsatmadagi 220–330 Om — <strong>5V manba</strong> uchun. <strong>9V batareya</strong> bilan kamida <strong>470 Om</strong> qo&#39;ying: 220 Om da tok ≈ 32 mA bo&#39;ladi va LED qizib, ishdan chiqishi mumkin.</p><p>Rezistor kichik → tok katta → LED juda yorqin, qiziydi. Rezistor katta → tok kichik → LED xira yoki umuman yonmaydi (uslubiy ko&#39;rsatma).</p><h3 id="_6-ulash-tartibi-uslubiy-ko-rsatma-bo-yicha" tabindex="-1">6. Ulash tartibi (uslubiy ko&#39;rsatma bo&#39;yicha) <a class="header-anchor" href="#_6-ulash-tartibi-uslubiy-ko-rsatma-bo-yicha" aria-label="Permalink to &quot;6. Ulash tartibi (uslubiy ko&#39;rsatma bo&#39;yicha)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Manba (+)  →  DIP kontakt 1 (kirish)</span></span>
<span class="line"><span>DIP kontakt 1 (chiqish)  →  rezistor 330 Om</span></span>
<span class="line"><span>rezistor  →  LED anod (uzun oyoq, +)</span></span>
<span class="line"><span>LED katod (qisqa oyoq, −)  →  GND relsi</span></span>
<span class="line"><span>GND relsi  →  Manba (−)</span></span></code></pre></div><ol><li>DIP switch&#39;ni markaziy ariqcha ustiga tekis joylang.</li><li>Manba <code>+</code> ini qizil relsga, <code>−</code> ini ko&#39;k relsga ulang.</li><li>Qizil relsdan DIP kontaktining bir oyog&#39;iga sim torting.</li><li>Kontaktning qarama-qarshi oyog&#39;idan rezistor orqali LED anodiga.</li><li>LED katodini ko&#39;k (GND) relsga.</li><li>Hammasini tekshirib, so&#39;ng manbani yoqing. Richagni ON/OFF qilib LEDni kuzating.</li></ol><hr>`,26))]),i("div",D,[i("h2",v,[r(o,{name:"file-text"}),a[17]||(a[17]=t(" Amaliy mashg'ulot va topshiriqlar ",-1)),a[18]||(a[18]=i("a",{class:"header-anchor",href:"#amaliy-mashg-ulot-va-topshiriqlar","aria-label":`Permalink to "<Icon name="file-text" /> Amaliy mashg'ulot va topshiriqlar"`},"​",-1))]),a[19]||(a[19]=n('<h3 id="_1-topshiriq-breadboard-ulanishlarini-aniqlash-oson" tabindex="-1">1-topshiriq. Breadboard ulanishlarini aniqlash (oson) <a class="header-anchor" href="#_1-topshiriq-breadboard-ulanishlarini-aniqlash-oson" aria-label="Permalink to &quot;1-topshiriq. Breadboard ulanishlarini aniqlash (oson)&quot;">​</a></h3><p>Breadboard rasmida quyidagi juftliklar o&#39;zaro ulanganmi? <code>a5</code> va <code>e5</code>; <code>a5</code> va <code>a6</code>; <code>e10</code> va <code>f10</code>; yuqori qizil relsdagi 1- va 30-teshik.</p><p><strong>Yechim:</strong></p><ul><li><code>a5</code> va <code>e5</code> — <strong>ulangan</strong> (bir qatorning a–e qismi);</li><li><code>a5</code> va <code>a6</code> — <strong>ulanmagan</strong> (har xil qatorlar);</li><li><code>e10</code> va <code>f10</code> — <strong>ulanmagan</strong> (markaziy ariqcha ajratadi);</li><li>qizil relsning 1- va 30-teshigi — <strong>ulangan</strong> (rels butun uzunlik bo&#39;ylab). Eslatma: ba&#39;zi katta breadboardlarda relslar o&#39;rtada uzilgan bo&#39;ladi — multimetr bilan tekshiring.</li></ul><h3 id="_2-topshiriq-rezistorni-hisoblang-o-rta" tabindex="-1">2-topshiriq. Rezistorni hisoblang (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-rezistorni-hisoblang-o-rta" aria-label="Permalink to &quot;2-topshiriq. Rezistorni hisoblang (o&#39;rta)&quot;">​</a></h3><p>a) 5 V manba, yashil LED (3 V), tok 10 mA. b) 9 V batareya, qizil LED (2 V), tok 12 mA. Har biri uchun qarshilikni hisoblab, standart qatordan (220, 330, 470, 680, 1000 Om) mosini tanlang.</p><p><strong>Yechim:</strong></p><ul><li>a) R = (5 − 3) / 0,010 = <strong>200 Om</strong> → standartdan kattarog&#39;i <strong>220 Om</strong> (tok biroz kamayadi, xavfsiz).</li><li>b) R = (9 − 2) / 0,012 ≈ <strong>583 Om</strong> → <strong>680 Om</strong> (tok ≈ 10 mA). 470 Om ham mumkin (≈ 15 mA), lekin kattaroq tanlash xavfsizroq.</li></ul><p>Qoida: hisobdan chiqqan son standartda bo&#39;lmasa, <strong>kattaroq</strong> qiymat tanlanadi.</p><h3 id="_3-topshiriq-dip-switch-va-bitta-led-o-rta" tabindex="-1">3-topshiriq. DIP switch va bitta LED (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-dip-switch-va-bitta-led-o-rta" aria-label="Permalink to &quot;3-topshiriq. DIP switch va bitta LED (o&#39;rta)&quot;">​</a></h3><p>Tinkercad&#39;da: Breadboard Small, «DIP Switch DPST», qizil LED, 330 Om rezistor va 5 V manba (Power Supply komponenti, kuchlanishi 5 V ga sozlangan). Zanjirni yig&#39;ing, Start Simulation bosing va richagni ON/OFF qilib, ochiq va yopiq holatni ko&#39;rsating.</p><p><strong>Yechim:</strong></p><table tabindex="0"><thead><tr><th>Ulash</th><th>Qayerdan</th><th>Qayerga</th></tr></thead><tbody><tr><td>1</td><td>Manba <code>+</code></td><td>qizil rels</td></tr><tr><td>2</td><td>Manba <code>−</code></td><td>ko&#39;k rels</td></tr><tr><td>3</td><td>qizil rels</td><td>DIP 1-kontakt, yuqori oyoq</td></tr><tr><td>4</td><td>DIP 1-kontakt, pastki oyoq</td><td>330 Om rezistorning bir uchi</td></tr><tr><td>5</td><td>rezistorning ikkinchi uchi</td><td>LED anod</td></tr><tr><td>6</td><td>LED katod</td><td>ko&#39;k rels</td></tr></tbody></table><p>Natija: richag ON — LED yonadi (yopiq zanjir), OFF — o&#39;chadi (ochiq zanjir). Agar LED umuman yonmasa — LED teskari qo&#39;yilgan bo&#39;lishi mumkin (anod/katod), uni 180° burang.</p><h3 id="_4-topshiriq-ikki-kontakt-—-ikki-mustaqil-led-qiyin" tabindex="-1">4-topshiriq. Ikki kontakt — ikki mustaqil LED (qiyin) <a class="header-anchor" href="#_4-topshiriq-ikki-kontakt-—-ikki-mustaqil-led-qiyin" aria-label="Permalink to &quot;4-topshiriq. Ikki kontakt — ikki mustaqil LED (qiyin)&quot;">​</a></h3><p>DIP switch&#39;ning ikkala juftini ishlating: 1-kontakt Qizil LEDni, 2-kontakt Yashil LEDni boshqarsin (har biri o&#39;z rezistori bilan). 4 ta holat kombinatsiyasi uchun natija jadvalini to&#39;ldiring.</p><p><strong>Yechim:</strong> Har bir kontakt alohida zanjir: <code>+ → DIP1 → 330 Om → Qizil LED → GND</code> va <code>+ → DIP2 → 220 Om → Yashil LED → GND</code>. Ikki zanjir faqat <code>+</code> va GND relslari orqali umumiy.</p><table tabindex="0"><thead><tr><th>DIP1</th><th>DIP2</th><th>Qizil</th><th>Yashil</th></tr></thead><tbody><tr><td>OFF</td><td>OFF</td><td>o&#39;chiq</td><td>o&#39;chiq</td></tr><tr><td>ON</td><td>OFF</td><td>yoniq</td><td>o&#39;chiq</td></tr><tr><td>OFF</td><td>ON</td><td>o&#39;chiq</td><td>yoniq</td></tr><tr><td>ON</td><td>ON</td><td>yoniq</td><td>yoniq</td></tr></tbody></table><p>Xulosa: har bir juft kontakt <strong>mustaqil</strong> — biri ikkinchisiga ta&#39;sir qilmaydi (uslubiy ko&#39;rsatma: «har bir juft kontakt LEDni mustaqil ravishda yoqish yoki o&#39;chirish imkonini beradi»).</p><hr>',20))]),i("div",f,[i("h2",P,[r(o,{name:"file-text"}),a[20]||(a[20]=t(" Tezkor nazorat savollari ",-1)),a[21]||(a[21]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[22]||(a[22]=n("<ol><li>Elektr zanjirining asosiy qismlari qaysilar? <ul><li><em>Javob:</em> Manba, o&#39;tkazgich, iste&#39;molchi va kalit; LED zanjirida himoya uchun rezistor ham bo&#39;ladi.</li></ul></li><li>Ochiq zanjirda nima uchun LED yonmaydi? <ul><li><em>Javob:</em> Yo&#39;l uzilgan — tok manbaga qaytolmaydi, shuning uchun oqmaydi.</li></ul></li><li>DIP switch breadboardga nega markaziy ariqcha ustiga qo&#39;yiladi? <ul><li><em>Javob:</em> Har bir oyoq alohida qatorga tushishi va kontaktlar qisqa tutashmasligi uchun.</li></ul></li><li>DPST qisqartmasi nimani bildiradi? <ul><li><em>Javob:</em> Double Pole, Single Throw — ikki zanjir, har biri faqat yoq/o&#39;chir holatida.</li></ul></li><li>5 V manba va qizil LED (2 V) uchun 10 mA tokda qanday rezistor kerak? <ul><li><em>Javob:</em> (5 − 2) / 0,01 = 300 Om → 330 Om.</li></ul></li></ol><hr>",2))]),i("div",T,[i("h2",_,[r(o,{name:"file-text"}),a[23]||(a[23]=t(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[24]||(a[24]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[25]||(a[25]=n("<ul><li><strong>Komponentning ikki oyog&#39;i bir qatorda:</strong> rezistor yoki LED ning ikkala oyog&#39;i bitta 5 teshikli qatorga qo&#39;yilsa, ular «aylanib o&#39;tiladi» va zanjir ishlamaydi. Oyoqlar har doim <strong>turli</strong> qatorlarda bo&#39;lsin.</li><li><strong>DIP switch ariqcha ustiga qo&#39;yilmagan:</strong> juft kontaktlar bir qatorga tushib, kalit doim «yoqiq» bo&#39;lib qoladi. Ariqcha ustiga qo&#39;ying.</li><li><strong>LED teskari:</strong> uzun oyoq (anod) <code>+</code> tomonga, qisqa oyoq (katod) GND ga. Tinkercad&#39;da LED ustiga sichqonchani olib borsangiz, oyoq nomi chiqadi.</li><li><strong>Rezistorsiz ulash:</strong> 5 V yoki 9 V to&#39;g&#39;ridan-to&#39;g&#39;ri LEDga berilsa, u kuyadi (Tinkercad&#39;da LED ustida portlash belgisi chiqadi).</li><li><strong>9 V batareyada 220 Om:</strong> tok ≈ 32 mA — juda katta. 9 V uchun 470 Om yoki undan kattaroq qo&#39;ying.</li></ul>",1))])])}const w=l(h,[["render",I]]);export{V as __pageData,w as default};
